fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    let effective_rotation = n % len; // Calculate effective rotation
    if effective_rotation == 0 {
        return list.clone(); // No rotation needed
    }
    
    let split_index = len - effective_rotation; // Calculate the split index
    let suffix = &list[split_index..]; // Get the suffix
    let prefix = &list[..split_index]; // Get the prefix
    
    // Concatenate suffix and prefix to form the new rotated array
    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(suffix);
    new_list.extend_from_slice(prefix);
    
    new_list // Return the new rotated array
}